#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Enemies;
using MVZ2.GameContent.Damages;
using MVZ2.Vanilla.Enemies;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2.Vanilla.StateMachine;
using MVZ2Logic.Entities;
using PVZEngine.Buffs;
using PVZEngine.Damages;
using PVZEngine.Entities;
using PVZEngine.Timing;
using PVZEngine.Tools.Timing;
using UnityEngine;

namespace MVZ2.GameContent.Enemies
{
    public partial class FootballZombie
    {
        #region 状态机
        private class FootballStateMachine : EntityStateMachine
        {
            public FootballStateMachine()
            {
                AddState(new IdleState());
                AddState(new WalkState());
                AddState(new ImpactState());
                AddState(new AttackState());
                AddState(new DeathState());
            }
        }

        // 状态切换的总入口：按优先级算出“现在该处于什么状态”。
        private static void UpdateState(Entity zombie, bool restart = false)
        {
            var targetState = STATE_WALK;
            if (zombie.IsDead)
            {
                targetState = STATE_DEATH;
            }
            else if (zombie.IsPreviewEnemy())
            {
                targetState = STATE_IDLE;
            }
            else if (EnemyMeleeBehaviour.HasMeleeTarget(zombie))
            {
                // 面前有阻挡者 → 停下挥剑（硬直状态，不走路）
                targetState = STATE_MELEE_ATTACK;
            }
            if (stateMachine.GetStateNumber(zombie) != targetState || restart)
            {
                stateMachine.StartState(zombie, targetState);
            }
        }
        #endregion

        #region 空闲
        public class IdleState : EntityStateMachineState
        {
            public IdleState() : base(STATE_IDLE) { }
            public override void OnUpdateAI(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnUpdateAI(stateMachine, entity);
                UpdateState(entity);
            }
        }
        #endregion

        #region 行走（含出场冲刺）
        public class WalkState : EntityStateMachineState
        {
            public WalkState() : base(STATE_WALK) { }
            public override void OnUpdateAI(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnUpdateAI(stateMachine, entity);
                entity.UpdateWalkVelocity();
                // 还没冲撞过（出场冲刺阶段）：碰到第一个阻挡者就立即停下，
                // 缓存目标并进入冲撞动画；真正摧毁延迟到第 6 个逻辑帧结束。
                if (!IsCharged(entity) && EnemyMeleeBehaviour.HasMeleeTarget(entity))
                {
                    BeginImpact(entity);
                    stateMachine.StartState(entity, STATE_IMPACT);
                    return;
                }
                UpdateState(entity);
            }
        }
        #endregion

        #region 冲撞
        public class ImpactState : EntityStateMachineState
        {
            public ImpactState() : base(STATE_IMPACT) { }
            public override void OnEnter(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnEnter(stateMachine, entity);
                stateMachine.GetStateTimer(entity).ResetTime(IMPACT_DURATION_TICKS);
            }
            public override void OnUpdateLogic(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnUpdateLogic(stateMachine, entity);
                var stateTimer = stateMachine.GetStateTimer(entity);
                stateTimer.Run();
                if (stateTimer.PassedFrameFromMax(IMPACT_HIT_TICKS))
                {
                    ResolveImpact(entity);
                }
                if (!stateTimer.Expired)
                    return;
                DrawSword(entity);
                UpdateState(entity, true);
            }
        }
        #endregion

        #region 两段挥砍（硬直：攻击状态里没有移动逻辑）
        public class AttackState : EntityStateMachineState
        {
            public AttackState() : base(STATE_MELEE_ATTACK) { }
            public override void OnEnter(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnEnter(stateMachine, entity);
                var timer = GetAttackTimer(entity);
                timer.ResetTime(ATTACK_TOTAL_TICKS);
            }
            public override void OnUpdateAI(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnUpdateAI(stateMachine, entity);
                var stateTimer = GetAttackTimer(entity);
                stateTimer.Run();
                if (stateTimer.PassedFrameFromMax(ATTACK_HIT_1_TICK))
                {
                    Slash(entity);
                }
                if (stateTimer.PassedFrameFromMax(ATTACK_HIT_2_TICK))
                {
                    Slash(entity);
                }
                if (stateTimer.Expired)
                {
                    // 一个 1.5 秒周期结束：目标还在则重开一轮 attack，否则恢复行走。
                    UpdateState(entity, true);
                }
            }
            // 挥砍结算：对当前啃食目标造成一次 100 点伤害。
            private static void Slash(Entity entity)
            {
                var targetID = EnemyMeleeBehaviour.GetMeleeTarget(entity);
                var target = targetID?.GetEntity(entity.Level);
                if (target == null)
                    return;
                var damage = entity.GetDamage();
                var effects = new DamageEffectList(VanillaDamageEffects.MUTE, VanillaDamageEffects.ENEMY_MELEE);
                target.TakeDamage(damage, effects, entity);
            }
        }
        public const int SUBSTATE_SWING1 = 0;
        public const int SUBSTATE_SWING2 = 1;
        public const int SUBSTATE_RECOVER = 2;
        public const int ATTACK_DURATION_TICKS = 25; // attack 动画 0.8333 秒 × 30 TPS，只播一次
        public const int ATTACK_TOTAL_TICKS = 45;    // 攻击周期：25 tick 动画 + 20 tick 待机
        public const int ATTACK_HIT_1_TICK = 17;
        public const int ATTACK_HIT_2_TICK = 18;
        // 攻击状态专用的计时器字段（与状态机通用 StateTimer 分开），供动画行为读取当前段。
        public static readonly VanillaEntityPropertyMeta<FrameTimer> FIELD_ATTACK_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("FootballAttackTimer");
        public static FrameTimer GetAttackTimer(Entity entity)
        {
            var timer = entity.GetBehaviourField<FrameTimer>(FIELD_ATTACK_TIMER);
            if (timer == null)
            {
                timer = new FrameTimer();
                entity.SetBehaviourField(FIELD_ATTACK_TIMER, timer);
            }
            return timer;
        }
        #endregion

        #region 死亡
        public class DeathState : EntityStateMachineState
        {
            public DeathState() : base(STATE_DEATH) { }
            public override void OnEnter(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnEnter(stateMachine, entity);
                var stateTimer = stateMachine.GetStateTimer(entity);
                stateTimer.ResetSeconds(DEATH_SECONDS);
            }
            public override void OnUpdateLogic(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnUpdateLogic(stateMachine, entity);
                var stateTimer = stateMachine.GetStateTimer(entity);
                stateTimer.Run();
                if (stateTimer.Expired)
                {
                    entity.FaintRemove();
                }
                if (!entity.IsDead)
                {
                    UpdateState(entity, true);
                }
            }
            public const float DEATH_SECONDS = 2.5f;
        }
        #endregion

        public const int STATE_IDLE = LogicEnemyStates.IDLE;
        public const int STATE_WALK = LogicEnemyStates.WALK;
        public const int STATE_MELEE_ATTACK = LogicEnemyStates.MELEE_ATTACK;
        public const int STATE_DEATH = LogicEnemyStates.DEATH;
        public const int STATE_IMPACT = VanillaEnemyStates.FOOTBALL_ZOMBIE_IMPACT;
    }
}
